sources.python:
import sys, logging, time
print("TAIL_INIT")
logging.getLogger().setLevel(logging.DEBUG)
def handler(event, context):
    token=event['token']
    print('TAIL_BEGIN '+token)
    logging.debug('TAIL_DEBUG '+token)
    logging.warning('TAIL_WARN '+token)
    logging.error('TAIL_ERROR '+token)
    if event.get('unicode'): print('😀'*2200 + 'é'*event.get('pad',0))
    if event.get('partial'): sys.stdout.write('TAIL_PARTIAL '+token)
    else: print('TAIL_LAST '+token)
    if event.get('mode')=='error': raise ValueError('TAIL_FAILURE '+token)
    if event.get('mode')=='timeout': time.sleep(6)
    return {'token':token,'id':context.aws_request_id}

