console.log('TAIL_INIT');
const body = async (event, context) => {
 const token=event.token;
 console.log('TAIL_BEGIN '+token); console.debug('TAIL_DEBUG '+token); console.warn('TAIL_WARN '+token); console.error('TAIL_ERROR '+token);
 if(event.unicode) console.log('😀'.repeat(2200)+'é'.repeat(event.pad||0));
 if(event.partial) process.stdout.write('TAIL_PARTIAL '+token); else console.log('TAIL_LAST '+token);
 if(event.mode==='error') throw new Error('TAIL_FAILURE '+token);
 if(event.mode==='timeout') await new Promise(r=>setTimeout(r,6000));
 return {token,id:context.awsRequestId};
};
exports.handler=body;
exports.streaming=awslambda.streamifyResponse(async (event,stream,context)=>{stream.write('prefix');const result=await body(event,context);stream.end(JSON.stringify(result));console.log('TAIL_AFTER_STREAM '+event.token);});

